import React, { useState } from "react";
import {
  Button,
  Col,
  Label,
  Container,
  Row,
  FormGroup,
  Input,
  Form,
} from "reactstrap";
import "../Styles/UserRegister.css";

import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import { companySchemaValidation } from "../Validations/CompanyValidation";
import { useNavigate, Link } from "react-router-dom";

const MAJORS = [
  "",
  "Information Technology",
  "Business Administration",
  "Engineering",
  "Mass Communication",
];

const UserRegister = () => {
  const navigate = useNavigate();

  // State variables
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [major, setMajor] = useState("");
  const [age, setAge] = useState(0);

  // react-hook-form setup
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(companySchemaValidation),
  });

  // On form submit
  const onSubmit = (data) => {
    try {
      console.log("Form Data", data);
      alert("Student Registered ✅");
      localStorage.setItem("userData", JSON.stringify(data));
      navigate("/user-profile");
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <Container className="reg-page">
      <h1 className="reg-title">
        Create your <span className="accent">account</span>
      </h1>

      <div className="reg-card">
        <p className="reg-sub">Please fill in your details to continue</p>

        <Form className="div-form" onSubmit={handleSubmit(onSubmit)}>
          {/* Full Name */}
          <Row>
            <Col md={6}>
              <Label>Full Name</Label>
              <Input
                type="text"
                name="fullName"
                placeholder="Your name"
                {...register("fullName", {
                  value: fullName,
                  onChange: (e) => setFullName(e.target.value),
                })}
              />
              <p className="error">{errors.fullName?.message}</p>
            </Col>
          </Row>

          {/* Email */}
          <Row>
            <Col md={6}>
              <Label>Email</Label>
              <Input
                type="email"
                name="email"
                placeholder="you@example.com"
                {...register("email", {
                  value: email,
                  onChange: (e) => setEmail(e.target.value),
                })}
              />
              <p className="error">{errors.email?.message}</p>
            </Col>
          </Row>

          {/* Password */}
          <Row>
            <Col md={6}>
              <Label>Password</Label>
              <Input
                type="password"
                name="password"
                placeholder="********"
                {...register("password", {
                  value: password,
                  onChange: (e) => setPassword(e.target.value),
                })}
              />
              <p className="error">{errors.password?.message}</p>
            </Col>
          </Row>

          {/* Major */}
          <Row>
            <Col md={6}>
              <Label>Major</Label>
              <Input
                type="select"
                name="major"
                {...register("major", {
                  value: major,
                  onChange: (e) => setMajor(e.target.value),
                })}
              >
                {MAJORS.map((m, index) => (
                  <option key={index} value={m}>
                    {m === "" ? "Select your major" : m}
                  </option>
                ))}
              </Input>
              <p className="error">{errors.major?.message}</p>
            </Col>
          </Row>

          {/* Age */}
          <Row>
            <Col md={6}>
              <Label>Age</Label>
              <Input
                type="number"
                name="age"
                min="17"
                max="45"
                {...register("age", {
                  value: age,
                  onChange: (e) => setAge(e.target.value),
                })}
              />
              <p className="error">{errors.age?.message}</p>
            </Col>
          </Row>

          {/* Submit */}
          <Row>
            <Col md={6}>
              <Button className="reg-btn" color="success">
                Sign up
              </Button>
            </Col>
          </Row>

          {/* Login link */}
          <p className="login-text">
            Already have an account?{" "}
            <Link to="/login" className="login-link">
              Log in now!
            </Link>
          </p>
        </Form>
      </div>
    </Container>
  );
};

export default UserRegister;
